        Lists.newArrayList(new Path(base, "1"), new Path(base, "2")));
    try (AuditSpan span = span()) {
      fs.removeKeys(keys, false, null);
    }
  }

  private String join(final Iterable iterable) {
    return "[" + StringUtils.join(iterable, ",") + "]";
  }

